begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is(muse_private.import_isbn('1619634481'),'9781619634480','Database matching treats ISBN-10 and ISBN-13 as one identity');
select is(muse_private.import_title_key(' A–Book '),'a book','Database duplicate guard normalizes title punctuation');
insert into auth.users(id,email) values ('96000000-0000-0000-0000-000000000001','import-a@example.test'),('96000000-0000-0000-0000-000000000002','import-b@example.test');
set local role authenticated;
set local "request.jwt.claim.sub"='96000000-0000-0000-0000-000000000001';
select lives_ok($$select public.save_imported_book('96000000-0000-0000-0000-000000000010','goodreads','123','{"id":"96000000-0000-0000-0000-000000000020","title":"A Book","status":"planned","reviewEmojis":[]}',0,'{"title":"A Book"}','{"rating":4,"review":"A prior review"}','96000000-0000-0000-0000-000000000030')$$,'Book and attribution save together');
select lives_ok($$select public.save_imported_book('96000000-0000-0000-0000-000000000010','goodreads','123','{"id":"96000000-0000-0000-0000-000000000020","title":"A Book","status":"planned","reviewEmojis":[]}',0,'{"title":"A Book"}','{"rating":4,"review":"A prior review"}','96000000-0000-0000-0000-000000000030')$$,'Retry returns the original receipt');
select is((select count(*)::integer from public.book_import_observations),1,'Retry does not duplicate the observation');
select is((select count(*)::integer from public.whimsy_reading_sessions),0,'Import does not create reading sessions');
select throws_ok($$select public.save_imported_book('96000000-0000-0000-0000-000000000010','goodreads','123','{"id":"96000000-0000-0000-0000-000000000021","title":"Other","status":"planned","reviewEmojis":[]}',0,'{}',null,'96000000-0000-0000-0000-000000000031')$$,'23505',null,'Source cannot move to another book');
select lives_ok($$select public.save_imported_book('96000000-0000-0000-0000-000000000010','goodreads','456','{"id":"96000000-0000-0000-0000-000000000022","title":"Another Book","author":"Writer","isbn":"9781619634480","status":"planned","reviewEmojis":[]}',0,'{}',null,'96000000-0000-0000-0000-000000000032')$$,'A second book imports');
select throws_ok($$select public.save_imported_book('96000000-0000-0000-0000-000000000010','goodreads','789','{"id":"96000000-0000-0000-0000-000000000023","title":"Another Book","author":"Writer","isbn":"9781619634480","status":"planned","reviewEmojis":[]}',0,'{}',null,'96000000-0000-0000-0000-000000000033')$$,'23505',null,'A stale preview cannot insert the same book again');
set local "request.jwt.claim.sub"='96000000-0000-0000-0000-000000000002';
select is((select count(*)::integer from public.book_import_sources),0,'Another user cannot read import identities');
select is((select count(*)::integer from public.book_import_observations),0,'Another user cannot read historical reviews');
select * from finish();
rollback;
